unsigned char out[4] =
    {0x42, 0x4D, 0x00, 0xFF};
FILE *f = fopen("raw.bin", "wb");
fwrite(out, 1, 4, f);
fclose(f);
unsigned char in[4];
f = fopen("raw.bin", "rb");
size_t n = fread(in, 1, 4, f);
fclose(f);
printf("%zu bytes:", n);
for (size_t i = 0; i < n; i++)
    printf(" %02x", in[i]);

int b;
long count = 0;
while ((b = fgetc(in)) != EOF) {
    fputc(b, out);
    count++;
}
fclose(in);
fclose(out);
printf("copied %ld\n", count);
